def un_seul_vehicule(apps, schema_editor):
    """Coursiers existants : on garde le PREMIER type de véhicule servi (moto > tricycle > voiture)."""
    Partenaire = apps.get_model('courses', 'Partenaire')
    for p in Partenaire.objects.prefetch_related('categories__service'):
        cats = list(p.categories.all())
        services = [c.service.code for c in cats]
        garde = next((v for v in ('moto', 'tricycle', 'voiture') if v in services), None)
        if not garde:
            continue
        p.type_vehicule = garde
        p.climatise = any(c.code == 'voiture-climatisee' for c in cats)
        p.save(update_fields=['type_vehicule', 'climatise'])
        p.categories.set([c for c in cats if c.service.code == garde or c.service.code not in ('moto', 'tricycle', 'voiture')])


